create or replace function public.srk_admin_finalize_booking_bill(p_booking_id uuid)
returns public.srk_booking_final_bills
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
  v_booking public.service_bookings%rowtype;
  v_bill public.srk_booking_final_bills%rowtype;
  v_labour numeric(12,2):=0;
  v_material numeric(12,2);
  v_worker record;
  v_worker_gross numeric(12,2);
  v_worker_commission numeric(12,2);
  v_existing public.srk_booking_final_bills%rowtype;
  v_next_revision integer;
  v_tech_worked integer;
  v_helper_worked integer;
begin
  if not public.srk_has_admin_permission('bookings.manage') then
    raise exception 'Booking management permission required';
  end if;

  select * into v_booking
  from public.service_bookings
  where id=p_booking_id
  for update;

  if not found then raise exception 'Booking not found'; end if;

  -- Final Bill must be generated only after every assigned worker has
  -- completed their work and the Customer has a pending completion review.
  -- Customer approval happens AFTER the bill is issued, so status remains
  -- in_progress while completion_approval_status is pending.
  if v_booking.status is distinct from 'in_progress'
     or v_booking.completion_approval_status is distinct from 'pending'
     or v_booking.completion_requested_at is null
     or coalesce(v_booking.work_timer_running,false) then
    raise exception 'Final bill requires completed worker sessions and a pending Customer completion review';
  end if;

  if v_booking.payment_status='paid' then
    raise exception 'Paid booking cannot be rebilled';
  end if;
  if v_booking.commission_rate is null
     or v_booking.commission_rate<0
     or v_booking.commission_rate>100 then
    raise exception 'Booking commission snapshot is invalid';
  end if;

  select count(*) into v_tech_worked
  from public.srk_booking_workers bw
  where bw.booking_id=p_booking_id
    and bw.worker_role='technician'
    and bw.assignment_status in ('completed','released')
    and exists (
      select 1 from public.srk_worker_work_sessions s
      where s.booking_worker_id=bw.id and s.billable_seconds>0
    );

  select count(*) into v_helper_worked
  from public.srk_booking_workers bw
  where bw.booking_id=p_booking_id
    and bw.worker_role='helper'
    and bw.assignment_status in ('completed','released')
    and exists (
      select 1 from public.srk_worker_work_sessions s
      where s.booking_worker_id=bw.id and s.billable_seconds>0
    );

  if v_tech_worked<v_booking.requested_technician_count
     or v_helper_worked<v_booking.requested_helper_count then
    raise exception 'Requested number of Technicians/Helpers has not completed billable work';
  end if;

  if exists (
    select 1 from public.srk_booking_workers
    where booking_id=p_booking_id
      and assignment_status not in ('completed','released','cancelled','rejected')
  ) then
    raise exception 'All assigned workers must complete or be released before final billing';
  end if;

  if exists (
    select 1 from public.srk_worker_work_sessions s
    join public.srk_booking_workers bw on bw.id=s.booking_worker_id
    where bw.booking_id=p_booking_id
      and s.session_status not in ('completed','cancelled')
  ) then
    raise exception 'Every work session must be completed or cancelled before final billing';
  end if;

  for v_worker in
    select bw.id booking_worker_id,bw.worker_id,bw.worker_role,
      bw.hourly_rate_snapshot,
      coalesce(sum(s.billable_seconds),0)::bigint seconds
    from public.srk_booking_workers bw
    left join public.srk_worker_work_sessions s
      on s.booking_worker_id=bw.id
    where bw.booking_id=p_booking_id
      and bw.assignment_status in ('completed','released')
    group by bw.id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot
    having coalesce(sum(s.billable_seconds),0)>0
  loop
    if v_worker.hourly_rate_snapshot is null then
      raise exception 'Worker rate snapshot missing';
    end if;
    if v_worker.seconds>coalesce(v_booking.requested_duration_hours,1440)*3600 then
      raise exception 'Worker actual billable time exceeds booked maximum duration';
    end if;
    v_worker_gross:=round((v_worker.seconds::numeric/3600)*v_worker.hourly_rate_snapshot,2);
    v_labour:=v_labour+v_worker_gross;
  end loop;

  v_material:=coalesce(v_booking.materials_amount,0);

  select * into v_existing
  from public.srk_booking_final_bills
  where booking_id=p_booking_id
  for update;

  if found then
    if exists (
      select 1
      from public.srk_worker_earnings e
      join public.srk_worker_wallet_ledger l on l.earning_id=e.id
      where e.booking_id=p_booking_id
    ) then
      raise exception 'Final bill cannot be reissued after worker earnings have entered the wallet ledger; use refund/reconciliation';
    end if;

    if exists (
      select 1 from public.srk_booking_refund_requests r
      where r.booking_id=p_booking_id and r.status<>'rejected'
    ) then
      raise exception 'Final bill cannot be reissued while a refund request is active';
    end if;

    if v_existing.status in ('issued','approved','disputed') then
      raise exception 'An active final bill already exists';
    end if;

    v_next_revision:=v_existing.revision_no+1;

    insert into public.srk_booking_final_bill_revisions(
      bill_id,revision_no,previous_bill_data,previous_items,reason,archived_by
    )
    values(
      v_existing.id,v_existing.revision_no,to_jsonb(v_existing),
      coalesce((
        select jsonb_agg(to_jsonb(i) order by i.created_at)
        from public.srk_booking_final_bill_items i
        where i.bill_id=v_existing.id
      ),'[]'::jsonb),
      'Reissued after work reopening',auth.uid()
    );

    delete from public.srk_booking_final_bill_items
    where bill_id=v_existing.id;

    update public.srk_booking_final_bills
    set bill_number='SRK-BILL-'||lpad(nextval('public.srk_bill_number_seq')::text,6,'0'),
      revision_no=v_next_revision,service_amount=v_labour,
      materials_amount=v_material,discount_amount=0,tax_amount=0,
      status='issued',prepared_at=clock_timestamp(),updated_at=clock_timestamp()
    where id=v_existing.id
    returning * into v_bill;
  else
    insert into public.srk_booking_final_bills(
      booking_id,bill_number,revision_no,service_amount,
      materials_amount,status,prepared_at
    )
    values(
      p_booking_id,
      'SRK-BILL-'||lpad(nextval('public.srk_bill_number_seq')::text,6,'0'),
      1,v_labour,v_material,'issued',clock_timestamp()
    )
    returning * into v_bill;
  end if;

  insert into public.srk_booking_final_bill_items(
    bill_id,item_type,description,quantity,unit,unit_price
  )
  values(
    v_bill.id,'labour','Actual worker timer-based labour charges',
    1,'booking',v_labour
  );

  if v_material>0 then
    insert into public.srk_booking_final_bill_items(
      bill_id,item_type,description,quantity,unit,unit_price
    )
    values(
      v_bill.id,'material','Materials supplied (separate from commission)',
      1,'booking',v_material
    );
  end if;

  for v_worker in
    select bw.id booking_worker_id,bw.worker_id,bw.worker_role,
      bw.hourly_rate_snapshot,
      coalesce(sum(s.billable_seconds),0)::bigint seconds
    from public.srk_booking_workers bw
    left join public.srk_worker_work_sessions s
      on s.booking_worker_id=bw.id
    where bw.booking_id=p_booking_id
      and bw.assignment_status in ('completed','released')
    group by bw.id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot
    having coalesce(sum(s.billable_seconds),0)>0
  loop
    v_worker_gross:=round((v_worker.seconds::numeric/3600)*v_worker.hourly_rate_snapshot,2);
    v_worker_commission:=round(v_worker_gross*v_booking.commission_rate/100,2);

    insert into public.srk_worker_earnings(
      booking_id,booking_worker_id,worker_id,worker_role,bill_id,
      billable_seconds,gross_service_earning,company_commission_rate,
      company_commission,net_earning,payment_method,payout_status,settlement_status
    )
    values(
      p_booking_id,v_worker.booking_worker_id,v_worker.worker_id,
      v_worker.worker_role,v_bill.id,v_worker.seconds,
      v_worker_gross,v_booking.commission_rate,v_worker_commission,
      v_worker_gross-v_worker_commission,
      case when lower(v_booking.payment_method) in ('upi','card')
        then 'online' else lower(v_booking.payment_method) end,
      'pending','pending'
    )
    on conflict(booking_worker_id) do update
    set bill_id=excluded.bill_id,
      billable_seconds=excluded.billable_seconds,
      gross_service_earning=excluded.gross_service_earning,
      company_commission_rate=excluded.company_commission_rate,
      company_commission=excluded.company_commission,
      net_earning=excluded.net_earning,
      payment_method=excluded.payment_method,
      payout_status='pending',
      settlement_status='pending',
      updated_at=clock_timestamp();
  end loop;

  return v_bill;
end;
$function$;

alter table public.srk_worker_work_sessions
  add column if not exists worker_id uuid;

update public.srk_worker_work_sessions s
set worker_id=bw.worker_id
from public.srk_booking_workers bw
where bw.id=s.booking_worker_id and s.worker_id is null;

do $$
begin
  if exists(select 1 from public.srk_worker_work_sessions where worker_id is null) then
    raise exception 'Cannot enforce worker timer uniqueness: found session without linked worker';
  end if;
end $$;

alter table public.srk_worker_work_sessions
  alter column worker_id set not null;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid='public.srk_worker_work_sessions'::regclass
      and conname='srk_worker_work_sessions_worker_id_fkey'
  ) then
    alter table public.srk_worker_work_sessions
      add constraint srk_worker_work_sessions_worker_id_fkey
      foreign key(worker_id) references public.srk_worker_profiles(id);
  end if;
end $$;

create index if not exists srk_worker_work_sessions_worker_id_idx
  on public.srk_worker_work_sessions(worker_id);

create or replace function public.srk_set_work_session_worker()
returns trigger
language plpgsql
security definer
set search_path=pg_catalog,public
as $$
declare v_worker_id uuid;
begin
  select worker_id into v_worker_id
  from public.srk_booking_workers
  where id=new.booking_worker_id;
  if v_worker_id is null then
    raise exception 'Booking assignment not found';
  end if;
  if new.worker_id is not null and new.worker_id<>v_worker_id then
    raise exception 'Session worker must match booking assignment';
  end if;
  new.worker_id:=v_worker_id;
  return new;
end;
$$;

drop trigger if exists srk_set_work_session_worker_trg on public.srk_worker_work_sessions;
create trigger srk_set_work_session_worker_trg
before insert or update of booking_worker_id,worker_id
on public.srk_worker_work_sessions
